      "15. yüzyıl nesrinin dil ve edebiyat bakımından özellikleri, Tevarih-i Al-i Osman metinleri, dini ve tasavvufi metinler.",
      "Mesihinin Gül-i Sadbergden, Yazıcıoğlu Ahmed Bicannın Envarul-aşîkinden, Sinan Paşanın Tezkiretül-evliya ve Tazarrunameden örnekler.",
      "16. yüzyılda nesir türünün genel görünüşü ve tezkire geleneği.",
      "Aşık Çelebinin \"Meşâirüş Şuara\"dan, Kınalızade Hasan Çelebi ve tezkiresinden seçme metinler.",
      "17. yüzyılda nesir.",
      "Evliya Çelebi ve Seyahatnameden seçme metinler. Faizi ve Tezkire-i Zübdetül Eşar\"dan seçme metinler.",
      "18. yüzyılda nesir.",
      "Ramiz ve \"Adab-ı Zürafa\"dan seçme metinler.",
      "Esrar Dede ve tezkiresinden seçme metinler.",
      "Eski türk edebiyatında nesir ı: kapsam ve temel kavramlar",
      "Tarihsel dönem ve yazı çevresi",
