    "purpose": "Türk halk inançları alanındaki kaynakları, metinleri ve kuramsal yaklaşımları lisansüstü düzeyde değerlendirme yetkinliği kazandırmayı amaçlamaktadır.",
    "content": "Türk halk inançları; halk biliminin kavramsal çerçevesi, alan araştırması yöntemleri, sözlü kültür ve aktarım, anlatı ve şiir türleri, âşık ve tekke geleneği, inanç, töre ve ritüeller, mitolojik unsurlar, bağlam merkezli çözümleme boyutlarıyla ele alınır.",
