    "purpose": "Bu dersin amacı, Tanzimat sonrası Türk edebiyatı üzerine yapılan araştırmalarda başvurulan temel kaynakları — edebiyat tarihleri, gazete ve dergiler, arşiv belgeleri, hatıralar ve mektuplar gibi — tanıtmak; bu kaynakların incelenmesi, değerlendirilmesi ve bilimsel çalışmalarda etkin biçimde kullanılmasına yönelik yöntemleri ortaya koymaktır.",
    "content": "Bu derste, modern Türk edebiyatının başlangıcından itibaren belirli türler, temalar, sorunlar ve yazarlar çerçevesinde kapsamlı bir kaynakça araştırması yapılır. Bu kapsamda, dönemin önemli kaynak eserleri tanıtılır; bu eserler farklı yönleriyle tartışılır ve eleştirel bir yaklaşımla değerlendirilir.",
