    "instructor": "Prof. Dr. AHMET DEMİRTAŞ",
    "purpose": "Bu dersin amacı, Türkçenin söz dizimsel yapısını kuramsal ve uygulamalı düzeyde inceleyerek öğrencilerin Türkçe cümle yapısını ve sözcük öbeklerini doğru biçimde analiz edebilmelerini sağlamaktır. Türkçenin söz diziminin temel ilkeleri, belirtme ve yargı grupları ile isim, sıfat, edat, fiil ve diğer sözcük gruplarının yapısal özellikleri ele alınır. Ayrıca öğrencilerin yüklemlerine, anlamlarına, söz dizimine ve yapılarına göre cümle türlerini tanımlayıp basit, birleşik, sıralı, bağlı, ara sözlü ve eksiltili cümleleri biçimsel ve anlamsal açıdan değerlendirebilmeleri hedeflenir.",
    "content": "Türkçenin söz diziminin temel özellikleri. Sözcük öbeklerinin yapısı ve özellikleri. Belirtme grupları ve yargı grupları. Belirtme gruplarının temel özellikleri ve türleri. İsim Tamlamaları, Sıfat Tamlamaları, Birleşik İsim, Tekrar Grubu, Aitlik Grubu, Edat Grubu, Ünvan Grubu, Birleşik Fiiller, İsim Fiil Grubu, Sıfat Fiil Grubu, Zarf Fiil Grubu, Sayı Grubu, Ünlem Grubu, Bağlama Grubu, Kısaltma Grupları. Cümle ve özellikleri. Cümlenin Ögeleri. Yüklemlerine göre cümleler. Anlamlarına göre cümleler. Söz dizimine göre cümleler. Yapılarına göre cümleler. Basit ve Birleşik Cümleler. Şartlı Birleşik Cümle. İçiçe Birleşik Cümle. Ki’li Birleşik Cümle. Girişik Birleşik Cümle. Sıralı Cümle. Bağımlı ve Bağımsız Sıralı Cümle. Bağlı Cümle. Bağımlı ve Bağımsız Sıralı Cümle. Ara Sözlü/Ara Cümleli Cümle. Eksiltili Cümle.",
    "methods": "Düz Anlatım Yöntemi",
