    "name": "ANLATIBİLİM II",
    "type": "Seçmeli",
    "credit": 3,
    "ects": 6,
    "theory": 3,
    "practice": 0,
    "term": "Bahar",
    "instructor": "Doç. Dr. BİRSEL SAĞIROĞLU",
    "purpose": "Bu dersin amacı, Anlatıbilim I kapsamında edinilen temel kuramsal bilgileri ileri düzeyde geliştirmek; öğrencilerin anlatı kuramlarını eleştirel bir bakış açısıyla değerlendirebilmelerini ve farklı anlatı türlerine uygulayabilmelerini sağlamaktır. Ders, anlatı çözümleme yöntemlerini derinleştirmeyi, klasik ve çağdaş anlatı kuramları arasındaki ilişkileri kavratmayı ve öğrencilerin disiplinler arası anlatı analizleri yapabilme becerilerini geliştirmeyi hedefler.",
    "content": "Bu ders kapsamında anlatı kuramlarının ileri düzey tartışmaları ele alınır. Yapısalcı ve post-yapısalcı anlatı kuramları, anlatıcı ve odaklanma türleri, zaman ve mekân kurgusu, anlatı düzeyleri, metinlerarasılık, üst kurmaca, güvenilmez anlatıcı, bakış açısı ve söylem analizi gibi konular incelenir. Edebî metinler başta olmak üzere sinema, tiyatro ve yeni medya anlatıları üzerinden uygulamalı çözümlemeler yapılır. Kuramsal metin okumaları ile örnek metin incelemeleri birlikte yürütülür.",
    "methods": "Anlatım, tartışma temelli öğrenme, metin çözümlemesi, küçük grup çalışmaları, karşılaştırmalı analiz, öğrenci sunumları, eleştirel okuma, proje ve araştırma temelli öğrenme, soru-cevap, geri bildirim.",
    "resources": "Dersin gerçek OBS kaynakları; birincil edebî metinler, güncel Türk dili ve edebiyatı araştırmaları, kütüphane katalogları ve hakemli makaleler.",
